  const reason = await stopAgent($, agentId)

  if (reason !== null) {
    $.ui.toast(stopFailure(agent, reason))

    return
  }
  await addComm($, { from: 'deck', kind: 'action', text: 'stop', to: agentId })
  $.ui.toast(`Stopping ${agent.nickname}.`)
